#include "tf_framework.h"

// ---------------------------------------------------------------------------
// tm_float_edges.cpp
//
// Float-boundary inputs to the converting Trapezoid move API (cmd 2), with the
// MOSFETs DISABLED throughout. This probes the float->internal->int32 pipeline
// in Servomotor::trapezoidMove(float,float):
//     displacement_internal = displacement * CONVERSION_FACTOR_SHAFT_ROTATIONS
//     trapezoidMoveRaw((int32_t)displacement_internal, (uint32_t)duration_internal)
// (see Arduino_library/Servomotor.cpp and AutoGeneratedUnitConversions.h;
//  COUNTS_PER_REVOLUTION == 3276800, CONVERSION_FACTOR_SHAFT_ROTATIONS ==
//  3276800.0f, CONVERSION_FACTOR_SECONDS == 31250.0f).
//
// GROUND TRUTH used here:
//   * With the MOSFETs off, a queued trapezoid still advances the *commanded*
//     position (get_motor_position() == current_position_i96.position in
//     firmware/Src/motor_control.c), while the shaft does not move. Get position
//     returns that commanded value (main.c GET_POSITION_COMMAND).
//   * The per-tick deviation check trips fatal ERROR_POSITION_DEVIATION_TOO_LARGE
//     (code 45; python_programs/servomotor/error_codes.json) only when
//     |commanded - measured| exceeds the limit. The default limit is TWO shaft
//     rotations (motor_control.c: DEFAULT_MAX_ALLOWABLE_POSITION_DEVIATION =
//     ONE_REVOLUTION_MICROSTEPS * 2). Ten 0.1-rot moves accumulate ONE rotation
//     of commanded advance, which is under the 2-rotation limit, so no fatal 45
//     is expected here. The trapezoidMoveRaw docstring notes moving with MOSFETs
//     off "typically trips" 45; the spec anticipates this, so if it arises we
//     recover and assert only that the code was exactly 45 (nothing weaker).
//
// Sub-cases (each ends with systemReset + drain):
//   (a) accumulation: 10 x trapezoidMove(0.1 rot) should leave the commanded
//       position within 200 counts of exactly 1.0 rotation (float rounding
//       characterization). 0.1f rounds to 327680 counts/move exactly on cast,
//       so the ideal total is 3276800 == COUNTS_PER_REVOLUTION.
//   (b) NaN and +Inf displacement: assert ONLY that the library call RETURNS
//       (no hang) and that after systemReset the device is fully healthy. We do
//       NOT assert what garbage int32 went on the wire ((int32_t)NaN / (int32_t)
//       Inf is implementation-defined). MOSFETs are off, so no motion results.
//   (c) negative-zero displacement behaves like a dwell (0-count move): no fatal
//       error and the commanded position is unchanged.
//   (d) denormal displacement (1e-40) behaves like a dwell for the same reason.
//
// SAFETY:
//   * MOSFETs DISABLED for the whole module -> the shaft never moves, regardless
//     of what displacement the garbage cast produces. No physical motion safety
//     concern; the "moves" only advance the commanded-position integrator.
//   * tfGetMotor() is unique-ID (extended) addressed, so every frame targets one
//     device -> collision-safe on the 39-motor rack. No raw bus injection, no
//     alias/broadcast single-target frames.
//   * No test-mode (cmd 36) values are used anywhere. Every wait loop is bounded
//     by a millis() timeout. After any induced fatal error we systemReset +
//     delay(1500) + drain before continuing.
// ---------------------------------------------------------------------------

static const int      NORMAL_RESET_DELAY_MS = 1500;   // wait after a plain reset
static const uint8_t  ERR_POS_DEVIATION     = 45;     // error_codes.json code 45
static const int64_t  COUNTS_PER_ROT        = 3276800;// COUNTS_PER_REVOLUTION
static const int64_t  ACCUM_TOLERANCE       = 200;    // counts, float-rounding budget
static const float    MOVE_DUR_S            = 0.2f;   // seconds per move (nonzero)

// Drain any bytes left in the RS485 RX buffer (bounded).
static void drainBus() {
    uint32_t t0 = millis();
    while (Serial1.available()) {
        Serial1.read();
        if (millis() - t0 > 500) break;
    }
}

// systemReset to a known-clean state: reset, wait out the no-response window,
// then drain. Used at start, between sub-cases, and after any induced fatal.
static void cleanReset(Servomotor* motor) {
    motor->systemReset();
    delay(NORMAL_RESET_DELAY_MS);  // no response during reset; don't check errors
    drainBus();
}

// Read the latched fatal error code via Get status (answered normally even in
// the fatal state). Returns 0xFF on a comms-layer failure so the caller can tell
// "no info" from "code 0".
static uint8_t readFatalCode(Servomotor* motor) {
    getStatusResponse st = motor->getStatus();
    if (motor->getError() != 0) {
        printf("  (getStatus comms error: %d)\n", motor->getError());
        return 0xFF;
    }
    return st.fatalErrorCode;
}

// Prove the device is alive at the application level by round-tripping a ping.
static bool pingRoundTrips(Servomotor* motor) {
    uint8_t payload[10];
    for (int i = 0; i < 10; i++) payload[i] = (uint8_t)(i * 3 + 5);
    pingResponse r = motor->ping(payload);
    if (motor->getError() != 0) {
        printf("  ping comms error %d\n", motor->getError());
        return false;
    }
    return memcmp(r.responsePayload, payload, 10) == 0;
}

// Poll the motion queue until it drains to empty, bounded by timeoutMs.
static uint8_t waitForIdle(Servomotor* motor, uint32_t timeoutMs) {
    uint8_t n = 0xFF;
    uint32_t t0 = millis();
    while (millis() - t0 < timeoutMs) {
        n = motor->getNQueuedItems();
        if (motor->getError() == 0 && n == 0) break;
        delay(10);
    }
    delay(100);  // settle margin
    return n;
}

void tm_float_edges(void) {
    Serial.println("test_ard_float_edges: BEGIN\n");

    Servomotor* motor = tfGetMotor();

    // ---- Clean, known starting state. ----
    cleanReset(motor);
    uint8_t startFatal = readFatalCode(motor);
    printf("Fatal error code after initial reset: %d\n", startFatal);
    TEST_RESULT("FE start: no fatal error after reset", startFatal == 0);

    motor->setTimeUnit(TimeUnit::SECONDS);
    motor->setPositionUnit(PositionUnit::SHAFT_ROTATIONS);

    // MOSFETs disabled for the ENTIRE module (they already are after reset;
    // make it explicit and idempotent).
    motor->disableMosfets();
    checkMotorError(*motor, "disableMosfets");

    // =======================================================================
    // (a) Accumulation: 10 x trapezoidMove(0.1 rot). With MOSFETs off the
    //     commanded position still advances; the ideal total is exactly 1.0
    //     rotation (3276800 counts). Characterize float rounding to <=200 counts.
    // =======================================================================
    printf("\n--- (a) accumulate 10 x 0.1 rot ---\n");

    int64_t startPos = motor->getPositionRaw();
    bool startPosOk  = (motor->getError() == 0);
    printf("start commanded position = %lld counts\n", (long long)startPos);

    uint8_t fatalDuring = 0;   // first nonzero fatal code seen while queueing
    for (int i = 0; i < 10; i++) {
        motor->trapezoidMove(0.1f, MOVE_DUR_S);
        // A latched fatal error stops the sequence; getNQueuedItems is not
        // answered normally in the fatal state, so check BEFORE waiting.
        uint8_t f = readFatalCode(motor);
        if (f != 0 && f != 0xFF) { fatalDuring = f; break; }
        uint8_t q = waitForIdle(motor, 4000);
        if (q != 0) printf("  move %d: queue did not drain (q=%d)\n", i, q);
    }

    if (fatalDuring == 0) {
        int64_t endPos = motor->getPositionRaw();
        bool endPosOk  = (motor->getError() == 0);
        int64_t expected = startPos + COUNTS_PER_ROT;
        int64_t delta = endPos - expected;
        printf("end commanded position = %lld counts (expected %lld, delta %lld)\n",
               (long long)endPos, (long long)expected, (long long)delta);
        TEST_RESULT("FE(a) 10x0.1rot accumulates to ~1.0 rot within 200 counts",
                    startPosOk && endPosOk &&
                    (delta < 0 ? -delta : delta) <= ACCUM_TOLERANCE);
    } else {
        // Spec-anticipated: with MOSFETs off the deviation check may fire. The
        // ONLY acceptable stop reason is the documented deviation fatal 45.
        printf("Accumulation stopped early by fatal code %d (expected %d if any)\n",
               (int)fatalDuring, (int)ERR_POS_DEVIATION);
        TEST_RESULT("FE(a) accumulation stopped only by expected deviation fatal (45)",
                    fatalDuring == ERR_POS_DEVIATION);  // error_codes.json code 45
    }

    // Recover to clean before the next sub-case (queue may hold items; a fatal
    // may be latched).
    cleanReset(motor);
    motor->disableMosfets();
    checkMotorError(*motor, "disableMosfets after (a)");

    // =======================================================================
    // (b) NaN and +Inf displacement. Assert ONLY that the library call returns
    //     (reaching the next line proves no hang) and that the device is fully
    //     healthy after systemReset. Do NOT assert the garbage that went on the
    //     wire. MOSFETs off -> no motion regardless.
    // =======================================================================
    printf("\n--- (b) NaN displacement ---\n");
    motor->trapezoidMove(NAN, MOVE_DUR_S);
    TEST_RESULT("FE(b) trapezoidMove(NaN) returns (no hang)", true);
    cleanReset(motor);
    uint8_t fatalAfterNan = readFatalCode(motor);
    printf("after NaN + reset: fatalCode=%d\n", (int)fatalAfterNan);
    TEST_RESULT("FE(b) no residual fatal after NaN + reset", fatalAfterNan == 0);
    TEST_RESULT("FE(b) device responsive (ping) after NaN + reset",
                pingRoundTrips(motor));

    printf("\n--- (b) +Inf displacement ---\n");
    motor->disableMosfets();
    checkMotorError(*motor, "disableMosfets before +Inf");
    motor->trapezoidMove(INFINITY, MOVE_DUR_S);
    TEST_RESULT("FE(b) trapezoidMove(+Inf) returns (no hang)", true);
    cleanReset(motor);
    uint8_t fatalAfterInf = readFatalCode(motor);
    printf("after +Inf + reset: fatalCode=%d\n", (int)fatalAfterInf);
    TEST_RESULT("FE(b) no residual fatal after +Inf + reset", fatalAfterInf == 0);
    TEST_RESULT("FE(b) device responsive (ping) after +Inf + reset",
                pingRoundTrips(motor));

    // =======================================================================
    // (c) Negative-zero displacement. -0.0f * factor == -0.0f, (int32_t)(-0.0f)
    //     == 0 -> a 0-count dwell: no fatal error, commanded position unchanged.
    // =======================================================================
    printf("\n--- (c) negative-zero displacement (dwell) ---\n");
    motor->disableMosfets();
    checkMotorError(*motor, "disableMosfets before -0.0");
    int64_t cBefore = motor->getPositionRaw();
    bool cBeforeOk  = (motor->getError() == 0);
    motor->trapezoidMove(-0.0f, MOVE_DUR_S);
    uint8_t cFatal = readFatalCode(motor);
    waitForIdle(motor, 4000);
    int64_t cAfter = motor->getPositionRaw();
    bool cAfterOk  = (motor->getError() == 0);
    printf("neg-zero: before=%lld after=%lld fatal=%d\n",
           (long long)cBefore, (long long)cAfter, (int)cFatal);
    TEST_RESULT("FE(c) -0.0 displacement raises no fatal error", cFatal == 0);
    TEST_RESULT("FE(c) -0.0 displacement leaves commanded position unchanged",
                cBeforeOk && cAfterOk && cAfter == cBefore);
    cleanReset(motor);

    // =======================================================================
    // (d) Denormal displacement (1e-40). 1e-40f * factor underflows to ~0, cast
    //     to int32 is 0 -> a 0-count dwell, identical behaviour to zero.
    // =======================================================================
    printf("\n--- (d) denormal displacement (1e-40, dwell) ---\n");
    motor->disableMosfets();
    checkMotorError(*motor, "disableMosfets before denormal");
    int64_t dBefore = motor->getPositionRaw();
    bool dBeforeOk  = (motor->getError() == 0);
    motor->trapezoidMove(1e-40f, MOVE_DUR_S);
    uint8_t dFatal = readFatalCode(motor);
    waitForIdle(motor, 4000);
    int64_t dAfter = motor->getPositionRaw();
    bool dAfterOk  = (motor->getError() == 0);
    printf("denormal: before=%lld after=%lld fatal=%d\n",
           (long long)dBefore, (long long)dAfter, (int)dFatal);
    TEST_RESULT("FE(d) denormal displacement raises no fatal error", dFatal == 0);
    TEST_RESULT("FE(d) denormal displacement leaves commanded position unchanged",
                dBeforeOk && dAfterOk && dAfter == dBefore);

    // ---- Leave the device clean and at rest. ----
    cleanReset(motor);
}
